/// Rules with no Apple documentation, and what mactriage relies on instead.
pub const NO_APPLE_DOC: &[(&str, &str)] = &[
    ("audit.install_history", "Apple publishes no documentation of /Library/Receipts/InstallHistory.plist; mactriage reads the install records macOS writes there (the same list System Information shows under Installations)."),
    ("correlate.story", "mactriage's own grouping of several findings from one process; no Apple document applies."),
    ("file.force_reset", "Apple publishes no documentation of ForceReset or SystemMemoryReset reports; mactriage relies on the report type in the report's own header (bug_type 151 / 301)."),
    ("file.gpu_restart", "Apple publishes no documentation of .gpuRestart reports; mactriage relies on the report file the GPU driver writes."),
    ("file.system_watchdog", "Apple documents app watchdog terminations (0x8badf00d) but not the system watchdog report; mactriage relies on the report type in the report's own header (bug_type 409)."),
    ("log.gpu_reset", "Apple publishes no documentation of GPU reset log messages; mactriage relies on the messages the GPU driver writes to the unified log."),
    ("log.launchd_services", "Apple documents how launchd jobs are configured but not launchd's abnormal-exit log messages; mactriage relies on those unified log messages."),
    ("log.shutdown_cause", "Apple publishes no list of \"Previous shutdown cause\" codes; mactriage relies on the SMC stop-cause constants published by the open-source VirtualSMC project."),
    ("log.watchdog", "Apple documents app watchdog terminations but not the system watchdog's log messages; mactriage relies on watchdogd's unified log messages."),
    ("sec.hosts_block", "Apple publishes no security guidance on /etc/hosts; mactriage relies on the hosts(5) file format and its own list of Apple update, OCSP and notarization hosts."),
    ("sec.hosts_redirect", "Apple publishes no security guidance on /etc/hosts; mactriage relies on the hosts(5) file format and its own list of sensitive hosts."),
    ("sec.jamf_broken", "Jamf Pro is documented by Jamf, not Apple; mactriage checks the jamf binary and the programs its LaunchDaemons start."),
    ("sec.jamf_checkin_stale", "Jamf Pro is documented by Jamf, not Apple; mactriage reads the check-in history in /var/log/jamf.log."),
    ("sec.jamf_unreachable", "Jamf Pro is documented by Jamf, not Apple; mactriage relies on `jamf checkJSSConnection`."),
    ("sec.managed_prefs", "Apple documents configuration profile payloads, not the /Library/Managed Preferences folder; mactriage reads the preference files macOS writes there."),
    ("sec.mdm_mismatch", "Apple documents the profile payloads but not a check that they are in effect; mactriage compares /Library/Managed Preferences with the live settings."),
    ("snap.lid_angle", "Apple publishes no documentation of the lid angle sensor; mactriage relies on the sensor's HID readings and the AppleClamshellState I/O registry key."),
];

/// Apple's meaning of a crash report's exception type.
pub fn exception_type(key: &str) -> Option<&'static Decoded> {
    let k = key;
    match k {
        "EXC_ARITHMETIC" => Some(&Decoded { next_step: None, cite: Cite { doc: &D089, says: "An arithmetic error ended the process, often a division by zero or a floating-point error." } }),
        "EXC_BAD_ACCESS" => Some(&Decoded { next_step: None, cite: Cite { doc: &D090, says: "A bad memory access ended the process. Apple pairs it with SIGSEGV (an invalid or out-of-bounds address) or SIGBUS (a misaligned or invalid address, or a pointer authentication failure)." } }),
        "EXC_BAD_INSTRUCTION" => Some(&Decoded { next_step: None, cite: Cite { doc: &D091, says: "On Intel Macs a trace trap or an illegal instruction appears as EXC_BAD_INSTRUCTION (SIGILL): the code hit an unrecoverable error check or an instruction the CPU cannot run." } }),
        "EXC_BREAKPOINT" => Some(&Decoded { next_step: None, cite: Cite { doc: &D091, says: "On Apple silicon a trace trap appears as EXC_BREAKPOINT (SIGTRAP). The Swift runtime and libraries such as Dispatch trap on purpose when they hit an unrecoverable error, and log the reason in the report." } }),
        "EXC_CRASH" => Some(&Decoded { next_step: None, cite: Cite { doc: &D092, says: "The process crashed; Apple says the accompanying signal (SIGABRT, SIGKILL, SIGQUIT, SIGSYS or SIGTERM) tells you which kind of crash it was." } }),
        "EXC_GUARD" => Some(&Decoded { next_step: None, cite: Cite { doc: &D093, says: "The process broke a guarded-resource rule, most often by closing or writing to a file descriptor the system had guarded (for example the SQLite file behind a database)." } }),
        "EXC_RESOURCE" => Some(&Decoded { next_step: None, cite: Cite { doc: &D018, says: "The system stopped the process for going over a resource limit (CPU, memory, disk writes or wakeups). With NON-FATAL CONDITION in the Exception Note the report was taken without terminating the process." } }),
        _ => None,
    }
}

/// Apple's meaning of the signal that ended a process.
pub fn signal(key: &str) -> Option<&'static Decoded> {
    let k = key;
    match k {
        "SIGABRT" => Some(&Decoded { next_step: None, cite: Cite { doc: &D094, says: "An abort signal, usually because the process called abort() itself, for example on an uncaught Objective-C or C++ exception. Another process allowed to manage its lifetime can also send it, and an app extension that takes too long to start gets one with subtype LAUNCH_HANG." } }),
        "SIGBUS" => Some(&Decoded { next_step: None, cite: Cite { doc: &D095, says: "A bus error: the process tried to use a misaligned or invalid memory address, or a pointer failed its authentication check." } }),
        "SIGILL" => Some(&Decoded { next_step: None, cite: Cite { doc: &D091, says: "An illegal instruction: the executable contains an instruction the CPU does not implement or cannot run (on Intel Macs also used for trace traps)." } }),
        "SIGKILL" => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "The operating system killed the process, often because a background task broke a rule, the device ran short of resources, or the user force-quit the app. The Termination Reason code says which." } }),
        "SIGQUIT" => Some(&Decoded { next_step: None, cite: Cite { doc: &D097, says: "Another process with the right to manage this one's lifetime asked it to quit." } }),
        "SIGSEGV" => Some(&Decoded { next_step: None, cite: Cite { doc: &D098, says: "A segmentation fault: the process tried to use an invalid or out-of-bounds memory address." } }),
        "SIGSYS" => Some(&Decoded { next_step: None, cite: Cite { doc: &D099, says: "The process made a system call that does not exist." } }),
        "SIGTERM" => Some(&Decoded { next_step: None, cite: Cite { doc: &D100, says: "A request to terminate, often sent shortly before SIGKILL so the process can exit cleanly." } }),
        "SIGTRAP" => Some(&Decoded { next_step: None, cite: Cite { doc: &D091, says: "A trace trap: the process stopped itself at an unrecoverable error check (Swift runtime errors, Dispatch misuse, fatalError, __builtin_trap)." } }),
        _ => None,
    }
}

/// Apple's meaning of an EXC_BAD_ACCESS subtype ("KERN_INVALID_ADDRESS at 0x…").
pub fn kern_subtype(key: &str) -> Option<&'static Decoded> {
    let k = key.split_whitespace().next().unwrap_or(key);
    match k {
        "KERN_INVALID_ADDRESS" => Some(&Decoded { next_step: None, cite: Cite { doc: &D101, says: "The crashed thread touched unmapped memory, either reading data or fetching an instruction. Apple's example of address 0x0 is a NULL pointer, and a trailing \"possible pointer authentication failure\" note marks a corrupted pointer on arm64e." } }),
        "KERN_MEMORY_ERROR" => Some(&Decoded { next_step: None, cite: Cite { doc: &D101, says: "The crashed thread touched memory that could not return data at that moment, such as a memory-mapped file that became unavailable." } }),
        "KERN_PROTECTION_FAILURE" => Some(&Decoded { next_step: None, cite: Cite { doc: &D101, says: "The crashed thread used a valid address that is protected, such as read-only or non-executable memory; the VM Region Info shows which kind." } }),
        _ => None,
    }
}

/// Apple's meaning of a termination reason: a well-known code first, then the namespace.
pub fn termination(namespace: &str, code: u64) -> Option<&'static Decoded> {
    match (namespace, code) {
        ("SPRINGBOARD" | "RUNNINGBOARD", 0x2182bad2) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0x2182bad2: the system killed the app because a background task did not finish in time." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0x2182bad3) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0x2182bad3: the system killed the app because a background URL session did not finish in time." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0x2182bad4) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0x2182bad4: the system killed the app because a background fetch did not finish in time." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0x8badf00d) => Some(&Decoded { next_step: Some("The app was killed for not responding, not for a coding fault in the crash itself. If it recurs, note what the app was doing (opening a large file, a network share, a slow disk); check this report for disk, network and memory findings; update the app."), cite: Cite { doc: &D096, says: "0x8badf00d (\"ate bad food\"): the system watchdog killed the app because it stopped responding, usually because its main thread was blocked for a long time." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xbaadca11) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0xbaadca11: the system killed the app because it did not report a CallKit call after a PushKit notification." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xbad22222) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0xbad22222: the system killed a VoIP app because it resumed too often." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xbaddd15c) => Some(&Decoded { next_step: Some("Free disk space: macOS killed the app to purge caches because storage was low."), cite: Cite { doc: &D096, says: "0xbaddd15c: the system killed the app to delete caches and reclaim disk space." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xc00010ff) => Some(&Decoded { next_step: Some("Check this report's thermal findings and the Mac's ventilation; if the Mac is not hot, update the app."), cite: Cite { doc: &D096, says: "0xc00010ff (\"cool off\"): the system killed the app because of a thermal event, which can be the device or the environment it ran in." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xc51bad01) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0xc51bad01: watchOS killed the app for using too much CPU in a background task." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xc51bad02) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0xc51bad02: watchOS killed the app because a background task did not finish in its allotted time." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xc51bad03) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0xc51bad03: watchOS killed the app because a background task did not finish in time while the whole system was busy." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xd00d2bad) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0xd00d2bad: the system killed the app for excessive use of key system resources." } }),
        ("SPRINGBOARD" | "RUNNINGBOARD", 0xdead10cc) => Some(&Decoded { next_step: None, cite: Cite { doc: &D096, says: "0xdead10cc (\"dead lock\"): the system killed the app because it held a file lock or SQLite database lock while suspended." } }),
        ("RUNNINGBOARD", _) => Some(&Decoded { next_step: Some("The system ended the process; check the termination code above, update the app, and look for memory pressure or thermal findings in the same window."), cite: Cite { doc: &D096, says: "Apple's example of a SIGKILL termination reason is namespace RUNNINGBOARD with code 0xdead10cc; the code within the namespace identifies the reason." } }),
        ("SPRINGBOARD", _) => Some(&Decoded { next_step: None, cite: Cite { doc: &D020, says: "Apple's watchdog examples report the kill under namespace SPRINGBOARD; the code identifies the reason." } }),
        _ => None,
    }
}

/// Apple's description of one crash-report field mactriage quotes as evidence.
pub fn crash_field(field: &str) -> Option<Reference> {
    match field {
        "asi" => Some(Cite { doc: &D019, says: "Application Specific Information: messages a framework or the process logged just before it exited, often the actual error text." }.reference()),
        "VM Region Info" => Some(Cite { doc: &D024, says: "For memory-access crashes, the VM Region Info shows where the faulting address sits relative to the process's memory regions." }.reference()),
        "namespace" => Some(Cite { doc: &D019, says: "The termination namespace is the category the system uses for why it ended the process; the code within it identifies the reason, or is the BSD signal number for namespace SIGNAL." }.reference()),
        _ => None,
    }
}

